CSS = """<style>.public-intro{max-width:82ch;margin:18px 0 22px;color:var(--muted);font-size:14px;line-height:1.78}.public-intro p{margin:0 0 12px}.section-title{margin:34px 0 10px;font-size:22px;font-weight:700}.section-note{max-width:78ch;color:var(--muted);font-size:14px;line-height:1.7;margin:0 0 18px}.formulas-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin-top:16px}.formula-card{border:1px solid rgba(242,242,244,.14);border-radius:18px;overflow:hidden;background:rgba(0,0,0,.20);display:flex;flex-direction:column}.formula-card img{width:100%;aspect-ratio:1/1;object-fit:cover}.formula-body{padding:15px 14px 16px;display:flex;flex-direction:column;gap:9px;flex:1}.formula-kicker{font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:rgba(242,242,244,.52);margin:0}.formula-card h3{font-size:16px;line-height:1.35;margin:0;color:var(--fg)}.formula-card p{font-size:13px;line-height:1.62;margin:0;color:var(--muted)}.formula-line{font-family:Georgia,'Times New Roman',serif;color:var(--fg)!important}.formula-open{display:inline-flex;align-items:center;justify-content:center;margin-top:8px;padding:9px 12px;border-radius:999px;border:1px solid rgba(242,242,244,.16);background:rgba(255,255,255,.04);font-size:12px;font-weight:700;color:var(--fg);text-decoration:none}.field-note{margin-top:20px;border:1px solid rgba(242,242,244,.12);border-radius:18px;background:rgba(0,0,0,.16);padding:16px;max-width:82ch;color:var(--muted);font-size:14px;line-height:1.75}@media(max-width:980px){.formulas-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:640px){.formulas-grid{grid-template-columns:1fr}}</style>"""
