def e(s): return html.escape(s, quote=True)

def write(path, content):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8")


def public_index(lang, t):
    cards = []
    for i, f in enumerate(FORMULAS, 1):
        cards.append(f'''<article class="formula-card"><img src="../../assets/public-formulas/{f['img']}" alt="{e(f['titles'][lang])}" loading="lazy"><div class="formula-body"><p class="formula-kicker">{e(t['formula_word'])} {i:02d}</p><h3>{e(f['titles'][lang])}</h3><p>{e(f['card'][lang])}</p><p class="formula-line">{e(f['line'][lang])}</p><a class="formula-open" href="/ {lang}/public/formulas/{f['slug']}/">{e(t['open'])}</a></div></article>'''.replace('/ '+lang, '/'+lang))
    return f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><title>Ashraellen — {e(t['public_title'])}</title><meta name="description" content="Ashraellen public field: selected formulas, publications, talks, and research notes."/><script>(function(){{const isGitHub=location.hostname.endsWith('github.io');const repo=location.pathname.split('/').filter(Boolean)[0];window.__BASE__=(isGitHub&&repo)?`/${{repo}}/`:`/`;}})();</script><link rel="stylesheet" href="../../assets/public.css"><script defer src="/assets/analytics.js"></script>{CSS}</head><body><div class="wrap"><div class="page"><header class="site-header"><p class="brand">Ashraellen</p><div class="menu"><a href="/{lang}/">{e(t['entry'])}</a> | <a href="/{lang}/research/">{e(t['research'])}</a> | <a href="/{lang}/books/">{e(t['books'])}</a></div></header><main class="main"><div class="content"><h1 class="h1">{e(t['public_title'])}</h1><p class="lead">{e(t['lead'])}</p><div class="public-intro"><p>{e(t['intro1'])}</p><p>{e(t['intro2'])}</p></div><div class="grid"><section class="card"><h2>{e(t['talks'])}</h2><p>{e(t['talks'])}: video, speech, and public forms of thought.</p><a href="/{lang}/public/talks/">{e(t['open'])}</a></section><section class="card"><h2>{e(t['posts'])}</h2><p>{e(t['posts'])}: formulas, fragments, reactions, and observations.</p><a href="/{lang}/public/posts/">{e(t['open'])}</a></section></div><h2 class="section-title">{e(t['selected'])}</h2><p class="section-note">{e(t['selected_note'])}</p><section class="formulas-grid">{''.join(cards)}</section><div class="field-note">{e(t['field_note'])}</div><div class="seal"><img id="sealImg" src="/assets/symbol.png" alt="Ashraellen symbol"><span>— mark of presence</span></div></div></main></div></div></body></html>'''


def formula_page(lang, t, f, idx):
    prev_link = f'<a class="btn" href="/{lang}/public/formulas/{FORMULAS[idx-2]["slug"]}/">{e(t["prev"])}</a>' if idx > 1 else ''
    next_link = f'<a class="btn" href="/{lang}/public/formulas/{FORMULAS[idx]["slug"]}/">{e(t["next"])}</a>' if idx < len(FORMULAS) else ''
    return f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><title>Ashraellen — {e(f['titles'][lang])}</title><meta name="description" content="{e(f['titles'][lang])} — Ashraellen public formula."/><script>(function(){{const isGitHub=location.hostname.endsWith('github.io');const repo=location.pathname.split('/').filter(Boolean)[0];window.__BASE__=(isGitHub&&repo)?`/${{repo}}/`:`/`;}})();</script><link rel="stylesheet" href="../../../../assets/public.css"><script defer src="/assets/analytics.js"></script>{PAGE_CSS}</head><body><div class="wrap"><div class="page"><header class="site-header"><p class="brand">Ashraellen</p><div class="menu"><a href="/{lang}/">{e(t['entry'])}</a> | <a href="/{lang}/public/">{e(t['public_title'])}</a> | <a href="/{lang}/research/">{e(t['research'])}</a></div></header><main class="main"><div class="content formula-page"><p class="kicker">{e(t['formula_word'])} {idx:02d}</p><h1 class="formula-title">{e(f['titles'][lang])}</h1><section class="formula-hero"><img src="../../../../assets/public-formulas/{f['img']}" alt="{e(f['titles'][lang])}"><div><p class="formula-line">{e(f['line'][lang])}</p><div class="block"><h2>{e(t['meaning'])}</h2><p>{e(f['card'][lang])}</p></div></div></section><section class="block"><h2>{e(t['full'])}</h2><p>{e(f['full'][lang])}</p></section><section class="block"><h2>{e(t['why'])}</h2><p>{e(f['why'][lang])}</p></section><section class="block"><h2>{e(t['note'])}</h2><p>{e(f['note'][lang])}</p></section><div class="nav-row"><a class="btn" href="/{lang}/public/">{e(t['back_public'])}</a>{prev_link}{next_link}</div><div class="seal"><img src="/assets/symbol.png" alt="Ashraellen symbol"><span>— mark of presence</span></div></div></main></div></div></body></html>'''

for lang, t in LANGS.items():
    write(Path(lang)/"public"/"index.html", public_index(lang, t))
    for idx, f in enumerate(FORMULAS, 1):
        write(Path(lang)/"public"/"formulas"/f["slug"]/"index.html", formula_page(lang,t,f,idx))

sitemap = Path('sitemap.xml')
if sitemap.exists():
    text = sitemap.read_text(encoding='utf-8')
    insert = []
    for lang in LANGS:
        for f in FORMULAS:
            url = f"  <url><loc>https://www.ashraellen.com/{lang}/public/formulas/{f['slug']}/</loc><priority>0.7</priority></url>"
            if url not in text:
                insert.append(url)
    if insert:
        text = text.replace('</urlset>', '\n' + '\n'.join(insert) + '\n</urlset>')
        sitemap.write_text(text, encoding='utf-8')

print('Generated multilingual public formula pages.')
